P=pathlib.Path(__file__).parent;names=['controller-candidate.py','policies.py','seed-contract.json','test-door-plan.py',pathlib.Path(__file__).name];pins={n:hashlib.sha256((P/n).read_bytes()).hexdigest() for n in names};r=subprocess.run([sys.executable,str(P/'test-door-plan.py')],capture_output=True,text=True);assert pins=={n:hashlib.sha256((P/n).read_bytes()).hexdigest() for n in names};j={'scope':'10pure Door candidate/seed contract tests only; no guest/input/liveRAM','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'platform':platform.platform(),'sources':pins,'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'guest_qualified':False};f=P/('door-plan-tests-'+platform.system().lower()+'.json');assert not f.exists();f.write_bytes((json.dumps(j,indent=2)+'\n').encode());print(json.dumps({'receipt':str(f),'returncode':r.returncode}));raise SystemExit(r.returncode)
